param([string]$Title='AI Memory',[string]$Message='Check desktop status.',[string]$WarningLevel='info'); $ErrorActionPreference='Stop'; try { Add-Type -AssemblyName System.Windows.Forms; Add-Type -AssemblyName System.Drawing; $memoryIcon=New-Object System.Windows.Forms.NotifyIcon; $memoryIcon.Icon=if ($WarningLevel -eq 'warning') {[System.Drawing.SystemIcons]::Warning} else {[System.Drawing.SystemIcons]::Information}; $memoryIcon.Text='AI Memory'; $memoryIcon.Visible=$true; $memoryTip=if ($WarningLevel -eq 'warning') {[System.Windows.Forms.ToolTipIcon]::Warning} else {[System.Windows.Forms.ToolTipIcon]::Info}; $memoryIcon.ShowBalloonTip(8000,$Title,$Message,$memoryTip); $memoryTimer=[Diagnostics.Stopwatch]::StartNew(); while ($memoryTimer.Elapsed.TotalSeconds -lt 8) { [System.Windows.Forms.Application]::DoEvents(); Start-Sleep -Milliseconds 100 }; $memoryIcon.Dispose(); exit 0 } catch { try { $memoryShell=New-Object -ComObject WScript.Shell; $null=$memoryShell.Popup($Message,10,$Title,48); exit 0 } catch { exit 1 } }
